import itertools

def partition_set(n):
    max_sum = n**2
    max_partitions = None

    for a in range(1, 3*n+1):
        for d in range(1, 3*n+1):
            for b in range(a + d, 3*n+1, d):
                for c in range(b + d, 3*n+1, d):
                    for e in range(c + d, 3*n+1, d):
                        for f in range(e + d, 3*n+1, d):
                            for g in range(f + d, 3*n+1, d):
                                if (a, b, c, e, f, g) == tuple(sorted((a, b, c, e, f, g))):
                                    partition = [[a, a+d, a+2*d], [b, b+d, b+2*d], [c, c+d, c+2*d], [e, e+d, e+2*d], [f, f+d, f+2*d], [g, g+d, g+2*d]]
                                    S = sum([partition[i][1] - partition[i][0] for i in range(3)])
                                    if S == max_sum and partition not in max_partitions:
                                        max_partitions = [partition]

    return max_partitions

